import {normalizeRunKinds} from './workflow.js?v=0.12.0';
export const miles = s => s.endOdometer == null ? null : Number((s.endOdometer - s.startOdometer).toFixed(3));
export function validateOdometers(start,end){if(!Number.isFinite(start)||start<0||!Number.isFinite(end)||end<start)throw Error('Ending odometer must be at least the starting reading.');}
export const reimbursement = s => s.rate == null || miles(s)==null ? null : Math.round((miles(s)*s.rate+Number.EPSILON)*100)/100;
export function mikeReport(s,deliveries,runs){return [`Delivery Report — ${new Date(s.startedAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`,`Shift: ${new Date(s.startedAt).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})} – ${new Date(s.endedAt).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}`,'',`Starting odometer: ${s.startOdometer}`,`Ending odometer: ${s.endOdometer}`,`Total miles: ${miles(s)}`,'',`Deliveries completed: ${deliveries.filter(d=>d.shiftId===s.id&&d.status==='delivered').length}`,`Delivery runs: ${runs.filter(r=>r.shiftId===s.id).length}`,`Catering deliveries: ${deliveries.filter(d=>d.shiftId===s.id&&d.status==='delivered'&&d.isCatering).length}`,`Scheduled deliveries: ${deliveries.filter(d=>d.shiftId===s.id&&d.status==='delivered'&&d.scheduledAt).length}` ,...(s.fieldTestNote?['',s.fieldTestNote]:[]),...(taskLabels(s.tasks).length?['','Tasks completed:',...taskLabels(s.tasks).map(t=>'• '+t)]:[])].join('\n');}
export function mapsURL(addresses,restaurant){const plan=routePlan(addresses,restaurant),u=new URL('https://maps.apple.com/directions');u.searchParams.set('mode','driving');u.searchParams.set('destination',plan.destination);for(const a of plan.waypoints)u.searchParams.append('waypoint',a);return u.href.replaceAll('+','%20');}

export function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
export function validateBackup(v){if(v?.format!=='delivery-manager'||v.version!==1||!v.data)throw Error('This is not a supported Delivery Manager backup.');const d=v.data;if(d.addressNotes!=null&&(typeof d.addressNotes!=='object'||Array.isArray(d.addressNotes)||Object.values(d.addressNotes).some(n=>!n||(n.barkingDog!=null&&typeof n.barkingDog!=='boolean')||(n.doNotText!=null&&typeof n.doNotText!=='boolean'))))throw Error('Invalid address notes.');for(const k of ['shifts','deliveries','runs','customers','audit'])if(!Array.isArray(d[k]))throw Error('Backup is missing records.');if(!d.settings||typeof d.settings.restaurant!=='string'||typeof d.settings.mike!=='string')throw Error('Backup settings are invalid.');for(const k of ['shifts','deliveries','runs','customers','audit']){const ids=new Set();for(const x of d[k]){if(!x||typeof x.id!=='string'||ids.has(x.id))throw Error('Backup has missing or duplicate record IDs.');ids.add(x.id);}}const shiftIds=new Set(d.shifts.map(s=>s.id));if(d.shifts.filter(s=>s.status==='active').length>1)throw Error('Backup contains multiple active shifts.');for(const s of d.shifts){if(s.fieldTestNote!=null&&(typeof s.fieldTestNote!=='string'||s.fieldTestNote.length>2000))throw Error('Invalid shift note.');if(s.tasks!=null&&(typeof s.tasks!=='object'||Array.isArray(s.tasks)||Object.entries(s.tasks).some(([k,v])=>k==='special'?typeof v!=='string':typeof v!=='boolean')))throw Error('Invalid shift tasks.');if(!['active','finalized'].includes(s.status)||!Number.isFinite(s.startOdometer)||s.startOdometer<0||!Number.isFinite(Date.parse(s.startedAt)))throw Error('Invalid shift.');if(s.rate!=null&&(!Number.isFinite(s.rate)||s.rate<0))throw Error('Invalid reimbursement rate.');if(s.status==='finalized'){validateOdometers(s.startOdometer,s.endOdometer);if(!Number.isFinite(Date.parse(s.endedAt)))throw Error('Invalid shift ending time.');}}for(const x of d.deliveries)if(!shiftIds.has(x.shiftId)||!['pending','ready','active','delivered','canceled'].includes(x.status)||typeof x.address!=='string'||typeof x.name!=='string'||typeof x.phone!=='string')throw Error('Invalid delivery.');for(const x of d.deliveries){if(x.notes!=null&&(typeof x.notes!=='string'||x.notes.length>4000))throw Error('Invalid delivery notes.');if(x.cateringPhotoException!=null&&(!x.isCatering||!Number.isFinite(Date.parse(x.cateringPhotoException.confirmedAt))||typeof x.cateringPhotoException.reason!=='string'))throw Error('Invalid catering photo exception.');if(x.cateringPhotos!=null){if(typeof x.cateringPhotos!=='object')throw Error('Invalid catering photos.');for(const [key,p] of Object.entries(x.cateringPhotos)){if(!['setup','receipt'].includes(key)||!p||typeof p.data!=='string'||p.data.length>4e6||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(p.data))throw Error('Invalid catering photo.');}}}const deliveryIds=new Set(d.deliveries.map(x=>x.id));for(const r of d.runs)if(['completedDeliveryIds','unfinishedDeliveryIds'].some(key=>r[key]!=null&&(!Array.isArray(r[key])||r[key].some(id=>!r.deliveryIds?.includes(id))))||!shiftIds.has(r.shiftId)||!Array.isArray(r.deliveryIds)||r.deliveryIds.some(id=>!deliveryIds.has(id))||!['active','returned'].includes(r.status))throw Error('Invalid run.');return d;}
export const CUSTOMER_MESSAGE='Your food from Srivilai Thai Cuisine has been delivered!';
export function seattleAddress(address){const a=address.trim();if(!a)return '';return /\bSeattle\b/i.test(a)?a.replace(/\bSeattle\s*$/i,'Seattle, WA'):/(?:,\s*|\s+)(?:WA|Washington)(?:\s+\d{5}(?:-\d{4})?)?\s*$/i.test(a)?a:`${a}, Seattle, WA`;}
export function scheduledInstant(shiftStart,clock){if(!/^\d{2}:\d{2}$/.test(clock))throw Error('Choose a scheduled time.');const d=new Date(shiftStart);const [h,m]=clock.split(':').map(Number);if(h>23||m>59)throw Error('Invalid time.');d.setHours(h,m,0,0);return d.toISOString();}
export function scheduledStats(deliveries){const completed=deliveries.filter(d=>d.status==='delivered'&&d.scheduledAt&&d.completedAt);return {total:completed.length,onTime:completed.filter(d=>Date.parse(d.completedAt)<=Date.parse(d.scheduledAt)).length};}
export function periodRange(view,anchor=new Date()){const a=new Date(anchor),b=new Date(anchor);a.setHours(0,0,0,0);b.setHours(0,0,0,0);if(view==='weekly'){a.setDate(a.getDate()-((a.getDay()+6)%7));b.setTime(a.getTime());b.setDate(b.getDate()+6);}else if(view==='monthly'){a.setDate(1);b.setMonth(b.getMonth()+1,0);}else{a.setMonth(0,1);b.setMonth(11,31);}const day=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return {from:day(a),to:day(b)};}
export function paginate(items,page=0,size=10){const pages=Math.max(1,Math.ceil(items.length/size)),current=Math.min(Math.max(0,page),pages-1);return {items:items.slice(current*size,(current+1)*size),page:current,pages,total:items.length};}
export function shiftEndState(state,shiftId){const unresolved=state.deliveries.filter(d=>d.shiftId===shiftId&&['pending','ready','active'].includes(d.status));const openRuns=state.runs.filter(r=>r.shiftId===shiftId&&r.status==='active');const incompleteRuns=openRuns.filter(r=>r.deliveryIds.some(id=>!state.deliveries.some(d=>d.id===id&&['delivered','canceled'].includes(d.status))));return {unresolved,openRuns,incompleteRuns,canEnd:!unresolved.length&&!incompleteRuns.length};}
export function purgeCustomers(state,ids){const selected=new Set(ids),deliveryIds=new Set(state.deliveries.filter(d=>selected.has(d.customerId)).map(d=>d.id));state.customers=state.customers.filter(c=>!selected.has(c.id));for(const d of state.deliveries)if(deliveryIds.has(d.id)){d.name='Deleted customer';d.address='Redacted';d.phone='';d.customerId=null;delete d.cateringPhotos;}state.audit=state.audit.filter(a=>!deliveryIds.has(a.entityId)&&!selected.has(a.entityId));}
export function appendBatchOrder(state,shiftId,batchId,order){const batch=state.deliveries.filter(d=>d.shiftId===shiftId&&d.batchId===batchId&&d.status!=='canceled');if(!batch.length)throw Error('This batch is no longer available.');const open=state.runs.some(r=>r.shiftId===shiftId&&r.batchId===batchId&&r.status==='active');if(!open&&batch.every(d=>d.status==='delivered'))throw Error('This batch is already complete. Start a new batch.');state.deliveries.push({...order,shiftId,batchId,deliveryMode:'batch',status:'pending'});}
export function correctionReason(value){const reason=String(value??'').trim();if(!reason)throw Error('Enter a reason for this correction.');return reason;}
export const needsColdItemConfirmation=delivery=>!!delivery.hasColdItems&&!delivery.coldItemsConfirmedAt;
export function navigationAddress(value){const address=seattleAddress(value);return /\b(?:USA|United States)\s*$/i.test(address)?address:`${address}, United States`;}
export function routePlan(addresses){const stops=addresses.map(navigationAddress);if(!stops.length)throw Error('No delivery stops in this route.');return {waypoints:stops.slice(0,-1),destination:stops.at(-1)};}
export function changeDeliveryAddress(state,deliveryId,value){const address=String(value??'').trim();if(!address)throw Error('Enter a delivery address.');const delivery=state.deliveries.find(d=>d.id===deliveryId);if(!delivery)throw Error('Delivery not found.');const previous=delivery.address;delivery.address=address;for(const run of state.runs.filter(r=>r.deliveryIds.includes(deliveryId)))run.addressesChanged=true;return {previous,address};}
export function validateShiftMileage(state,shiftId,start,end){validateOdometers(start,end);const count=state.deliveries.filter(d=>d.shiftId===shiftId&&d.status==='delivered').length;if(end>start&&count===0)throw Error('Mileage changed, but no deliveries are marked completed for this shift. Correct the odometer readings, or return to Deliveries to finish recording your work.');}
export function runsByKind(runs,shiftIds,kind){const ids=new Set(shiftIds);return runs.filter(r=>ids.has(r.shiftId)&&(r.kind||(r.deliveryIds.length>1?'batch':r.deliveryIds.length===1?'single':'unknown'))===kind).sort((a,b)=>Date.parse(b.startedAt)-Date.parse(a.startedAt));}
export function requiredYesNo(value,label){if(value!=='yes'&&value!=='no')throw Error(`Choose Yes or No for ${label}.`);return value==='yes';}
export function deleteFinalizedShift(state,shiftId){const shift=state.shifts.find(s=>s.id===shiftId);if(!shift)throw Error('Shift not found.');if(shift.status!=='finalized')throw Error('Only completed shifts can be deleted from History.');const deliveryIds=new Set(state.deliveries.filter(d=>d.shiftId===shiftId).map(d=>d.id)),runIds=new Set(state.runs.filter(r=>r.shiftId===shiftId).map(r=>r.id));state.shifts=state.shifts.filter(s=>s.id!==shiftId);state.deliveries=state.deliveries.filter(d=>!deliveryIds.has(d.id));state.runs=state.runs.filter(r=>!runIds.has(r.id));state.audit=state.audit.filter(a=>a.entityId!==shiftId&&!deliveryIds.has(a.entityId)&&!runIds.has(a.entityId));return {deliveries:deliveryIds.size,runs:runIds.size};}
export function deleteFinalizedShifts(state,shiftIds){const ids=[...new Set(shiftIds)];if(!ids.length)throw Error('Select at least one shift.');for(const id of ids){const shift=state.shifts.find(s=>s.id===id);if(!shift||shift.status!=='finalized')throw Error('Only completed shifts can be deleted.');}for(const id of ids)deleteFinalizedShift(state,id);return ids.length;}
export function prioritizeOngoing(deliveries,runs){const activeIds=new Set(runs.filter(r=>r.status==='active').flatMap(r=>r.deliveryIds)),activeBatches=new Set(runs.filter(r=>r.status==='active'&&r.batchId).map(r=>r.batchId));const rank=d=>d.status==='active'||activeIds.has(d.id)||activeBatches.has(d.batchId)?0:1;return [...deliveries].sort((a,b)=>rank(a)-rank(b)||Date.parse(b.enteredAt)-Date.parse(a.enteredAt));}
export function reportDateRange(from,to){if((from&&!/^\d{4}-\d{2}-\d{2}$/.test(from))||(to&&!/^\d{4}-\d{2}-\d{2}$/.test(to)))throw Error('Choose valid report dates.');if(from&&to&&from>to)throw Error('Choose an end date on or after the start date.');return {from,to};}

// Final drop-off records completion; only explicit End Run records a restaurant return.
export function completeRuns(state,shiftId,at){for(const r of state.runs){if(r.status!=='active'||(shiftId&&r.shiftId!==shiftId))continue;const stops=state.deliveries.filter(d=>d.shiftId===r.shiftId&&(r.deliveryIds.includes(d.id)||(r.batchId&&d.batchId===r.batchId)));if(stops.length&&stops.every(d=>['delivered','canceled'].includes(d.status))){r.completedAt=r.completedAt||at||stops.map(d=>d.completedAt).filter(Boolean).sort().at(-1)||r.startedAt;r.completionKind='awaiting-return';r.completedDeliveryIds=stops.filter(d=>d.status==='delivered'&&r.deliveryIds.includes(d.id)).map(d=>d.id);}else{delete r.completedAt;delete r.completionKind;delete r.completedDeliveryIds;}}normalizeRunKinds(state);}
export function formatPhone(value){const raw=String(value||''),digits=raw.replace(/\D/g,'');if((raw.startsWith('+')&&!raw.startsWith('+1'))||digits.length>11)return raw;const prefix=digits.length===11&&digits.startsWith('1')?'1-':'',n=prefix?digits.slice(1):digits;return prefix+[n.slice(0,3),n.slice(3,6),n.slice(6)].filter(Boolean).join('-');}
export const addressKey=value=>seattleAddress(String(value||'')).toLowerCase().replace(/\bwashington\b/g,'wa').replace(/\bwa[ ,]+\d{5}(?:-\d{4})?\b/g,'wa').replace(/\bunited states\b|\busa\b/g,'').replace(/[^a-z0-9]/g,'');
export const TASK_GROUPS=[{id:'patio',label:'Sweep patio and sidewalk'},{id:'icecream',label:'Scoop to-go ice cream'},{id:'bigrock',label:'Big Rock Ice Cubes',children:['New cubes put in the freezer','Completed cubes removed and stored']},{id:'juice',label:'Juice',children:['Lime','Lemon','Grapefruit','Pineapple']},{id:'fruit',label:'Clean and wrap fruit',children:['Lemons','Grapefruit','Oranges']},{id:'syrup',label:'Syrups',children:['Simple syrup','Old fashioned syrup']}];
export function taskLabels(tasks={}){return TASK_GROUPS.flatMap(g=>g.children?g.children.filter(c=>tasks[`${g.id}:${c}`]).map(c=>`${g.label}: ${c}`):tasks[g.id]?[g.label]:[]).concat(tasks.special?.trim()?[tasks.special.trim()]:[]);}
export function reminderDue(shift,at=new Date()){if(!shift||shift.status!=='active'||Date.parse(shift.reminderAfter||0)>at.getTime())return false;const parts=date=>Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date).map(p=>[p.type,p.value])),p=parts(at),start=parts(new Date(shift.startedAt)),key=p=>`${p.year}-${p.month}-${p.day}`;return key(p)>key(start)||key(p)===key(start)&&Number(p.hour)*60+Number(p.minute)>=(['Fri','Sat'].includes(p.weekday)?1290:1260);}

export function awaitingReturn(state){return state.runs.find(r=>r.status==='active'&&r.completionKind==='awaiting-return'&&state.shifts.some(s=>s.id===r.shiftId&&s.status==='active'));}
export function endRun(state,at){const r=awaitingReturn(state);if(!r)throw Error('No run is waiting for a return.');if(!Number.isFinite(Date.parse(at))||Date.parse(at)<Date.parse(r.completedAt))throw Error('Return time cannot precede the final delivery.');r.returnedAt=at;r.status='returned';r.completionKind='restaurant-return';return r;}
